import { defineConfig } from "@tanstack/start/config";

export default defineConfig({
  server: {
    port: 47821,
    preset: "node-server",
  },
  vite: {
    plugins: [],
  },
});

import { createRouter as createTanStackRouter } from "@tanstack/react-router";
import { routerWithQueryClient } from "@tanstack/react-router-with-query";
import { QueryClient } from "@tanstack/react-query";
import { routeTree } from "./routeTree.gen";

export function createRouter() {
  const queryClient = new QueryClient({
    defaultOptions: {
      queries: {
        staleTime: 0,
      },
    },
  });

  const router = routerWithQueryClient(
    createTanStackRouter({
      routeTree,
      context: { queryClient },
      scrollRestoration: true,
    }),
    queryClient
  );

  return router;
}

declare module "@tanstack/react-router" {
  interface Register {
    router: ReturnType<typeof createRouter>;
  }
}

import { hydrateRoot } from "react-dom/client";
import { StartClient } from "@tanstack/start";
import { createRouter } from "./router";

const router = createRouter();

hydrateRoot(document, <StartClient router={router} />);

import {
  createStartHandler,
  defaultStreamHandler,
} from "@tanstack/start/server";
import { createRouter } from "./router";

export default createStartHandler({
  createRouter,
})(defaultStreamHandler);

export interface Comment {
  id: string;
  parentId: string | null;
  body: string;
  createdAt: number;
}

// In-memory store — persists for the lifetime of the server process
const comments: Comment[] = [
  {
    id: "1",
    parentId: null,
    body: "Welcome to the comment thread!",
    createdAt: Date.now() - 10000,
  },
  {
    id: "2",
    parentId: "1",
    body: "Thanks! Happy to be here.",
    createdAt: Date.now() - 8000,
  },
  {
    id: "3",
    parentId: "2",
    body: "Same here — love the nested replies.",
    createdAt: Date.now() - 6000,
  },
];

let nextId = 4;

export function getComments(): Comment[] {
  return comments;
}

export function createComment(
  parentId: string | null,
  body: string
): Comment {
  const comment: Comment = {
    id: String(nextId++),
    parentId,
    body,
    createdAt: Date.now(),
  };
  comments.push(comment);
  return comment;
}

import { createAPIFileRoute } from "@tanstack/start/api";
import { getComments, createComment } from "../../store";

export const APIRoute = createAPIFileRoute("/api/comments")({
  GET: async () => {
    const comments = getComments();
    return new Response(JSON.stringify(comments), {
      status: 200,
      headers: { "Content-Type": "application/json" },
    });
  },

  POST: async ({ request }) => {
    const url = new URL(request.url);
    const shouldFail = url.searchParams.get("fail") === "1";

    // Parse request body
    let body: { parentId: string | null; body: string };
    try {
      body = await request.json();
    } catch {
      return new Response(JSON.stringify({ error: "Invalid JSON" }), {
        status: 400,
        headers: { "Content-Type": "application/json" },
      });
    }

    if (!body.body || typeof body.body !== "string") {
      return new Response(JSON.stringify({ error: "body is required" }), {
        status: 400,
        headers: { "Content-Type": "application/json" },
      });
    }

    // Artificial delay of at least 300ms so optimistic update is observable
    await new Promise((resolve) => setTimeout(resolve, 350));

    if (shouldFail) {
      return new Response(
        JSON.stringify({ error: "Forced server error" }),
        {
          status: 500,
          headers: { "Content-Type": "application/json" },
        }
      );
    }

    const comment = createComment(body.parentId ?? null, body.body);
    return new Response(JSON.stringify(comment), {
      status: 200,
      headers: { "Content-Type": "application/json" },
    });
  },
});

